# ---- p2: registers for the formatting work on branch p2 ----
# p2fon and p2fys: while a character style is updated, the format walk changes only the runs of style p2fys-1. Both rest at zero, so the walk's filter is never read otherwise.
p2fon=R(); p2fys=R(); p2sc=R(); p2so=R(); p2sa=R(); p2sb=R(); p2mk=R(); p2x0=R(); p2x1=R(); p2x2=R(); p2xh=R(); p2rs=R(); p2rsr=R(); p2ln=R(); p2wrs=R(); p2bo=R(); p2p=R(); p2o=R(); p2b=R(); p2l=R(); p2nid=R(); p2old=R(); p2fl=R(); p2pe=R(); p2m=R(); p2w=R()   # p2m: what the selection walk changes (0 a link, 1 caps, 2 small caps); p2w: set (1) or clear (0)   # p2pe: the extended field (caps, small caps, ...) a paragraph style gives its runs   # list restart flag in layout, while reading, the last numbered numId read, and while saving
